  const l = u8.length, n = ((l + 9 + 63) >> 6) << 6; const m = new Uint8Array(n); m.set(u8); m[l] = 128;
  const dv = new DataView(m.buffer); dv.setUint32(n - 8, Math.floor(l / 536870912)); dv.setUint32(n - 4, (l << 3) >>> 0);
